const storedValues=[
 {code:'GROUP-HORIZON-12',category:'Discount',applied:'Room Only',value:'$20.00 / night',amount:20,kind:'night',expires:'Dec 31'},
 {code:'CEDAR-WELCOME-10',category:'Discount',applied:'Add-ons',value:'10%',amount:.1,kind:'addons',expires:'Dec 31'},
 {code:'EXTENDED-STAY-30',category:'Discount',applied:'Room Only',value:'20%',amount:.2,kind:'rooms',expires:'Dec 31'},
 {code:'RETREAT-VOUCHER-100',category:'Voucher',applied:'Bearer',value:'$100.00',amount:100,expires:'Jun 30'},
 {code:'CAFE-GIFT-25',category:'Gift Card',applied:'Bearer',value:'$25.00',amount:25,expires:'Dec 31'},
 {code:'BENEFACTOR-CREDIT',category:'Credit',applied:'—',value:'$250.00',amount:250,expires:'Dec 31'}
];
let storedCategory='All',storedDraft=null;
function availableStoredValues(){return [...storedValues,...(state.customStoredValues||[])];}
function storedCategoryTag(category){return '<span class="badge stored-category-tag '+(category==='Credit'?'stored-credit':['Voucher','Gift Card'].includes(category)?'stored-voucher':'stored-discount')+'">'+esc(category)+'</span>';}
const storedOverlayBase=renderOverlay,storedHandleBase=handle,storedTotalsBase=totals;
function storedAdjustment(q,t){const x=q?.storedValue;if(!x)return 0;return Math.min(t.total,Math.round((x.kind==='night'?q.rooms.reduce((s,r)=>s+r.qty,0)*nights()*x.amount:x.kind==='rooms'?t.rooms*x.amount:x.kind==='addons'?t.addons*x.amount:x.kind==='total'?t.total*x.amount:x.amount)*100)/100);}
totals=function(q=state.quote||wizard){const t=storedTotalsBase(q);if(!q?.storedValue)return t;const amount=storedAdjustment(q,t),total=Math.round((t.total-amount)*100)/100;return {...t,storedValueAmount:amount,total,deposit:Math.round(total*.5*100)/100};};
renderOverlay=function(){if(modal==='stored-create'){document.body.style.overflow='hidden';$('#overlay').innerHTML=pickerShell('Add New Stored Value','<form id="stored-create-form" class="stack">'+field('Code','code','','text','required maxlength="80"')+'<div class="grid2">'+select('Category','category','Discount',['Discount','Voucher','Gift Card','Credit'])+select('Applied to','applied','Room Only',['Room Only','Add-ons','Bearer'])+'</div><div class="grid2">'+select('Value type','valueType','Fixed amount',['Fixed amount','Percentage','Per night'])+field('Value','amount','','number','required min="0.01" step="0.01"')+'</div>'+field('Expires','expires','2026-12-31','date','required')+'</form>',button('Cancel','stored-new-cancel')+button('Save','stored-new-save','primary'),true).replace('figma-picker ','figma-picker stored-create-modal ');return;}if(modal==='stored-values'){document.body.style.overflow='hidden';const rows=availableStoredValues().filter(x=>storedCategory==='All'||x.category===({Discounts:'Discount',Vouchers:'Voucher','Gift Cards':'Gift Card',Credits:'Credit'})[storedCategory]).map(x=>[button(esc(x.code),'stored-select-'+x.code,'link'),storedCategoryTag(x.category),esc(x.applied),x.value,'<span class="badge success">Active</span>',x.expires]);$('#overlay').innerHTML=pickerShell('All Stored Values','<div class="row between picker-search"><label class="stored-search-field"><span class="stored-search-icon">'+img('cd2f1.svg')+'</span><input name="stored-search" aria-label="Search stored values" placeholder="Search stored values"></label>'+button('Add New','stored-new')+'</div><div class="row mb stored-tabs">'+['All','Discounts','Vouchers','Gift Cards','Credits'].map(x=>button(x,'stored-category-'+x,storedCategory===x?'primary':'')).join('')+'</div>'+table(['CODE','CATEGORY','APPLIED TO','VALUE','STATUS','EXPIRES'],rows)+(storedDraft?'<p class="mt">Selected: '+esc(storedDraft.code)+' · '+storedDraft.value+'</p>':''),button('Cancel','stored-cancel')+button('Apply','stored-apply','primary',!storedDraft)).replace('figma-picker ','figma-picker stored-values-modal ');return;}
 storedOverlayBase();if(modal==='reservation'&&resWizard?.step===2){const t=totals(),q=state.quote,container=$('#overlay .modal-content');if(!container)return;container.innerHTML=stepper(['Reservation info','Review & book'],2)+'<div class="panel stored-review"><div class="panel-body"><h3>Space</h3>'+line(q.spaceDays+' × '+esc(q.space)+' (per day)',money(t.space))+'<h3>Rooms ('+nights()+' nights)</h3>'+q.rooms.filter(r=>r.qty>0).map(r=>line(r.qty+' × '+esc(r.type)+' for '+nights()+' nights',money(r.qty*r.rate*nights()))).join('')+'<h3>Add-ons</h3>'+line(q.cateringQty+' × Group Catering (per guest-day)',money(q.cateringQty*q.cateringRate))+(q.extraAddons||[]).map(x=>line(x.qty+' × '+esc(x.title),money(x.qty*x.rate))).join('')+'</div></div><div class="panel stored-review mt"><div class="panel-body">'+line('Total',money(t.subtotal))+line('Taxes',money(t.tax))+(q.storedValue?line('Stored Value · '+esc(q.storedValue.code),'−'+money(t.storedValueAmount)):'')+line('Grand Total',money(t.total),'total')+'</div></div><label class="field mt"><span>Stored Value</span><button type="button" class="stored-value-field" data-action="stored-open"><span>'+esc(q.storedValue?.code||'Apply a discount, voucher or credit')+'</span>'+img('stored-value-ticket.svg')+'</button></label><p class="hint mt">Deposit '+money(q.payment?.amount||storedTotalsBase(q).deposit)+' already received. It will be carried to the reservation invoice.</p>';}
};
handle=function(a,el){if(a==='stored-new'){modal='stored-create';renderOverlay();return;}if(a==='stored-new-cancel'||['close-modal','picker-dismiss'].includes(a)&&modal==='stored-create'){modal='stored-values';renderOverlay();return;}if(a==='stored-new-save'){const f=$('#stored-create-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),amount=Number(v.amount),code=v.code.trim();if(!code||availableStoredValues().some(x=>x.code.toLowerCase()===code.toLowerCase())){$('#picker-error').textContent='Enter a unique stored value code.';return;}if(v.valueType==='Percentage'&&amount>100){$('#picker-error').textContent='Percentage must be between 0 and 100.';return;}const kind=v.valueType==='Per night'?'night':v.valueType==='Percentage'?(v.applied==='Room Only'?'rooms':v.applied==='Add-ons'?'addons':'total'):undefined;storedDraft={code,category:v.category,applied:v.applied,amount:v.valueType==='Percentage'?amount/100:amount,kind,value:v.valueType==='Percentage'?amount+'%':money(amount)+(kind==='night'?' / night':''),expires:dateLabel(v.expires).replace(/, \d{4}/,'')};(state.customStoredValues??=[]).push(storedDraft);storedCategory='All';save();modal='stored-values';renderOverlay();return;}if(a==='stored-open'){storedDraft=state.quote.storedValue||null;storedCategory='All';modal='stored-values';renderOverlay();return;}if(a==='stored-cancel'||a==='picker-dismiss'&&modal==='stored-values'||a==='close-modal'&&modal==='stored-values'){modal='reservation';renderOverlay();return;}if(a.startsWith('stored-category-')){storedCategory=a.slice(16);renderOverlay();return;}if(a.startsWith('stored-select-')){storedDraft=availableStoredValues().find(x=>x.code===a.slice(14));renderOverlay();return;}if(a==='stored-apply'){if(!storedDraft)return;state.quote.storedValue={...storedDraft};addEvent('Stored value '+storedDraft.code+' applied to reservation conversion.','Sam Patel');save();modal='reservation';renderOverlay();return;}const result=storedHandleBase(a,el);if(a==='book-reservation'&&state.reservation){state.reservation.storedValue=state.quote.storedValue||null;save();}return result;};
document.addEventListener('input',e=>{if(e.target.name==='stored-search'){const term=e.target.value.toLowerCase();$('#overlay').querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(term));}});

